/* Intent: Analyze digital engagement patterns by customer cohorts over time 
   Knowledge: Digital First Customer (id:14) and Customer Engagement Score (CES, id:7)
   Advanced Features: Date binning, FILTER clause */ WITH digital_cohorts AS (/* Step 1: Create quarterly cohorts based on customer tenure */ SELECT cr.clientref, TIMESTAMP_TRUNC((cr.scoredate - (cr.tenureyrs * INTERVAL '1' YEAR)), QUARTER) AS cohort_quarter, (bt.chaninvdatablock ->> '$.onlineuse' = 'High' OR bt.chaninvdatablock ->> '$.mobileuse' = 'High') /* Properly implement KB#14 Digital First Customer definition */ AND bt.chaninvdatablock ->> '$.autopay' = 'Yes' AS is_digital_first, 0.4 /* Calculate CES components */ * cah.produsescore + 0.3 * cah.chanusescore + 0.2 * bt.bankrelscore + 0.1 * (CAST(cah.custservint AS REAL) / 10) AS ces FROM core_record AS cr JOIN credit_accounts_and_history AS cah ON cr.coreregistry = cah.histcompref JOIN bank_and_transactions AS bt ON cah.histcompref = bt.bankexpref WHERE NOT bt.chaninvdatablock IS NULL) /* Step 2: Aggregate metrics by cohort and digital-first status */ SELECT cohort_quarter, is_digital_first, COUNT(*) AS cohort_size, AVG(ces) AS avg_ces /* CES metrics */, CAST(COUNT(*) /* Percentage with high engagement */ FILTER(WHERE ces > 0.7) AS REAL) / COUNT(*) AS pct_high_engagement, CAST(COUNT(*) /* Digital-first high engagement rate */ FILTER(WHERE is_digital_first AND ces > 0.7) AS REAL) / NULLIF(COUNT(*) FILTER(WHERE is_digital_first), 0) AS digital_first_high_engagement_rate FROM digital_cohorts GROUP BY cohort_quarter, is_digital_first ORDER BY cohort_quarter NULLS LAST, is_digital_first DESC NULLS FIRST

/* Intent: Analyze spread percentages across markets and correlate with market sentiment indicators 
   Knowledge Used: Spread Percentage (id:0)
   Advanced Features: JSONB operators, window functions, common table expressions */ WITH spread_calc AS (/* Step 1: Calculate spread percentage for each market using JSONB extraction */ SELECT (quote_depth_snapshot -> '$.metadata' ->> '$.mktcombo') AS market_pair, (CAST((quote_depth_snapshot -> '$.quotes' ->> '$.askquote') AS REAL) - CAST((quote_depth_snapshot -> '$.quotes' ->> '$.bidquote') AS REAL)) / CAST((quote_depth_snapshot -> '$.quotes' ->> '$.midquote') AS REAL) * 100 AS spread_pct, marketdatanode FROM marketdata), sentiment_data AS (/* Step 2: Extract market sentiment indicators from analytics */ SELECT mdataref, (market_sentiment_indicators -> '$.momentum' ->> '$.mktfeel') AS sentiment, CAST((market_sentiment_indicators -> '$.momentum' ->> '$.buyforce') AS REAL) AS buy_force FROM analyticsindicators) /* Step 3: Join and analyze spread vs sentiment with window functions */ SELECT s.market_pair, s.spread_pct, d.sentiment, d.buy_force, AVG(s.spread_pct) OVER (PARTITION BY d.sentiment) AS avg_spread_by_sentiment, PERCENT_RANK() OVER (ORDER BY s.spread_pct NULLS LAST) AS spread_percentile FROM spread_calc AS s JOIN sentiment_data AS d ON s.marketdatanode = d.mdataref ORDER BY s.spread_pct DESC NULLS FIRST

/* Intent: Track smart money flows and correlate with price movements 
   Knowledge Used: Smart Money Flow (id:15), Whale-Driven Market (id:46)
   Advanced Features: Temporal joins, advanced window functions */ WITH money_flows AS (/* Step 1: Extract flow data from analytics indicators */ SELECT CAST((md.quote_depth_snapshot -> '$.metadata' ->> '$.timetrack') AS TIMESTAMP) AS flow_time, (md.quote_depth_snapshot -> '$.metadata' ->> '$.mktcombo') AS market_pair, CAST((CAST((a.market_sentiment_indicators ->> '$.flow') AS JSONB) ->> '$.smartforce') AS REAL) AS smart_force, CAST((CAST((a.market_sentiment_indicators ->> '$.flow') AS JSONB) ->> '$.retailflow') AS REAL) AS retail_flow, CAST((CAST((a.market_sentiment_indicators ->> '$.flow') AS JSONB) ->> '$.instflow') AS REAL) AS inst_flow, (CAST((a.market_sentiment_indicators ->> '$.big_players') AS JSONB) ->> '$.whalemotion') AS whale_activity, CAST((md.quote_depth_snapshot -> '$.quotes' ->> '$.midquote') AS REAL) AS mid_price FROM analyticsindicators AS a JOIN marketdata AS md ON a.mdataref = md.marketdatanode), price_changes AS (/* Step 2: Calculate subsequent price changes */ SELECT mf.*, LEAD(mid_price, 1) OVER (PARTITION BY market_pair ORDER BY flow_time NULLS LAST) AS next_price_1h, LEAD(mid_price, 4) OVER (PARTITION BY market_pair ORDER BY flow_time NULLS LAST) AS next_price_4h, LEAD(mid_price, 24) OVER (PARTITION BY market_pair ORDER BY flow_time NULLS LAST) AS next_price_24h, CASE WHEN smart_force > retail_flow * 1.2 AND smart_force > inst_flow * 1.2 THEN 'Smart Money Dominant' WHEN retail_flow > smart_force * 1.2 AND retail_flow > inst_flow * 1.2 THEN 'Retail Dominant' WHEN inst_flow > smart_force * 1.2 AND inst_flow > retail_flow * 1.2 THEN 'Institutional Dominant' ELSE 'Mixed' END AS flow_dominance /* Smart money dominance calculation */ FROM money_flows AS mf) /* Step 3: Analyze flow impact on prices */ SELECT flow_dominance, whale_activity, AVG(next_price_1h - mid_price) AS avg_1h_change, AVG(next_price_4h - mid_price) AS avg_4h_change, AVG(next_price_24h - mid_price) AS avg_24h_change, CAST(SUM(CASE WHEN (smart_force > retail_flow AND smart_force > inst_flow AND next_price_4h > mid_price) OR (smart_force < retail_flow AND smart_force < inst_flow AND next_price_4h < mid_price) THEN 1 ELSE 0 END) /* Success rate of smart money direction */ AS REAL) / COUNT(*) AS smart_money_accuracy FROM price_changes WHERE NOT next_price_24h IS NULL GROUP BY flow_dominance, whale_activity, market_pair ORDER BY smart_money_accuracy DESC NULLS FIRST

/* Intent: Calculate Material Deterioration Rate (MDR) for artifacts and identify those in accelerated deterioration
   Knowledge used: #6 (Material Deterioration Rate), #13 (Accelerated Deterioration Scenario)
   Advanced functions: LATERAL JOIN, Conditional aggregation with FILTER, JSON functions */ /* Step 1: Calculate Material Deterioration Rate for each artifact using the formula from Knowledge #6 */ WITH MaterialDeterioration AS (SELECT art.ArtRegistry, art.ArtName, sens.SensitivityRegistry, JSON_BUILD_OBJECT('EnvSensitivity', sens.EnvSensitivity, 'LightSensitivity', sens.LightSensitivity, 'TempSensitivity', sens.TempSensitivity, 'HumiditySensitivity', sens.HumiditySensitivity, 'VibraSensitivity', sens.VibraSensitivity, 'PollutantSensitivity', sens.PollutantSensitivity, 'PestSensitivity', sens.PestSensitivity) AS sensitivities /* Create a JSON object with sensitivity values for easier processing */, (CASE WHEN sens.EnvSensitivity = 'High' THEN 1 ELSE 0 END + CASE WHEN sens.LightSensitivity = 'High' THEN 1 ELSE 0 END + CASE WHEN sens.TempSensitivity = 'High' THEN 1 ELSE 0 END + CASE WHEN sens.HumiditySensitivity = 'High' THEN 1 ELSE 0 END + CASE WHEN sens.VibraSensitivity = 'High' THEN 1 ELSE 0 END + CASE WHEN sens.PollutantSensitivity = 'High' THEN 1 ELSE 0 END + CASE WHEN sens.PestSensitivity = 'High' THEN 1 ELSE 0 END) AS high_sensitivity_count /* Count high sensitivity factors */ FROM ArtifactsCore AS art JOIN SensitivityData AS sens ON art.ArtRegistry = sens.ArtRef), LatestReadings /* Step 2: Get latest environmental readings for each showcase */ AS (SELECT ShowcaseRef, TempC, RelHumidity, ReadTimestamp FROM (SELECT env.ShowcaseRef AS ShowcaseRef, env.TempC AS TempC, env.RelHumidity AS RelHumidity, env.ReadTimestamp AS ReadTimestamp, ROW_NUMBER() OVER (PARTITION BY env.ShowcaseRef ORDER BY env.ShowcaseRef NULLS LAST, env.ReadTimestamp DESC NULLS FIRST) AS _row_number FROM EnvironmentalReadingsCore AS env) AS _t WHERE _row_number = 1), ArtifactMDR /* Step 3: Join artifacts with their showcases and calculate MDR */ AS (SELECT md.ArtRegistry, md.ArtName, md.high_sensitivity_count, ur.ShowcaseRefUsed, lr.TempC, lr.RelHumidity, (art.ArtAgeYears * CASE WHEN md.sensitivities ->> '$.EnvSensitivity' = 'Low' THEN 1 WHEN md.sensitivities ->> '$.EnvSensitivity' = 'Medium' THEN 5 WHEN md.sensitivities ->> '$.EnvSensitivity' = 'High' THEN 10 END * POWER((lr.RelHumidity - 50), 2) * lr.TempC) /* Calculate MDR using formula: (ArtAgeYears × ERF × (RelHumidity - 50)² × TempC) / 100000 */ / 100000.0 AS mdr FROM MaterialDeterioration AS md JOIN ArtifactsCore AS art ON md.ArtRegistry = art.ArtRegistry JOIN UsageRecords AS ur ON md.ArtRegistry = ur.ArtRefUsed LEFT JOIN LatestReadings AS lr ON ur.ShowcaseRefUsed = lr.ShowcaseRef) /* Step 4: Identify artifacts in accelerated deterioration (MDR > 5 and at least two high sensitivities) */ SELECT mdr.ArtRegistry, mdr.ArtName, mdr.TempC AS current_temp, mdr.RelHumidity AS current_humidity, mdr.high_sensitivity_count, CASE WHEN mdr.mdr > 5 AND mdr.high_sensitivity_count >= 2 THEN 'Yes' ELSE 'No' END AS accelerated_deterioration FROM ArtifactMDR AS mdr
